import pathlib,subprocess,os,json,shlex,tempfile
BASH=os.environ.get('OPSFORGE_BASH','bash')
def run(args=()):
 return subprocess.run([BASH,'-c','exec bash task.sh '+shlex.join(args)],capture_output=True,text=True,encoding='utf-8',timeout=10)
import tarfile,io
def make(name):
 with tarfile.open('bundle.tar','w')as t:
  i=tarfile.TarInfo(name);i.size=1;t.addfile(i,io.BytesIO(b'x'))
make('../escaped');assert run().returncode==2 and not pathlib.Path('output').exists()
make('safe/file');assert run().returncode==0 and pathlib.Path('output/safe/file').read_bytes()==b'x'
